const comHttp = u => (u && !/^https?:\/\//.test(u) ? 'http://' + u : u || '');   // Render manda host:porta
const EVO = comHttp($env.EVOLUTION_URL), INST = $env.EVOLUTION_INSTANCIA || 'nucleo';   // numero do Leo
const INST_JOAO = $env.EVOLUTION_INSTANCIA_JOAO || 'joao';                                  // chip do Joao
const evo = (method, caminho, body) => this.helpers.httpRequest({
  method, url: `${EVO}${caminho}`, headers: { apikey: $env.EVOLUTION_API_KEY }, body, json: true, timeout: 30000 });
// markdown -> formatacao do WhatsApp (*negrito*), sem cabecalhos
const paraWhatsapp = t => String(t || '').replace(/\*\*(.+?)\*\*/g, '*$1*').replace(/^#{1,6}\s*/gm, '');
async function whatsappConectado(inst = INST) {
  try { const r = await evo('GET', `/instance/connectionState/${inst}`); return (r.instance || r).state === 'open'; }
  catch { return false; }
}
async function enviarWhatsapp(numero, texto, marcar = true, inst = INST) {
  let t = paraWhatsapp(texto);
  if (marcar && !t.startsWith('🤖')) t = '🤖 ' + t;   // marca da IA: nunca responde a si mesma
  return evo('POST', `/message/sendText/${inst}`, { number: String(numero).replace(/\D/g, ''), text: t });
}
// nunca marcar conversas como lidas nem atender chamadas (importante no numero pessoal)
const CONFIG_INSTANCIA = { rejectCall: false, msgCall: '', groupsIgnore: true, alwaysOnline: false,
  readMessages: false, readStatus: false, syncFullHistory: false };
async function enviarTelegram(chatId, texto) {
  return this.helpers.httpRequest({ method: 'POST', json: true,
    url: `https://api.telegram.org/bot${$env.TELEGRAM_BOT_TOKEN}/sendMessage`, body: { chat_id: chatId, text: texto } });
}

// status / conectar (QR ou codigo de pareamento) / desconectar
const corpo = $input.first().json.r.corpo;
const I = corpo.instancia || INST;
const TOKEN = I === INST ? $env.WHATSAPP_WEBHOOK_SEGREDO : `${$env.WHATSAPP_WEBHOOK_SEGREDO}-${I}`;
const urlWebhook = comHttp($env.WHATSAPP_WEBHOOK_BASE || 'n8n:5678') + '/webhook/whatsapp';
const eventos = ['MESSAGES_UPSERT', 'CONNECTION_UPDATE'];
const cfgWebhook = { enabled: true, url: urlWebhook, byEvents: false, base64: true, events: eventos };
async function estado() {
  try { const x = await evo('GET', `/instance/connectionState/${I}`); return (x.instance || x).state || 'close'; }
  catch (e) { return /404|not exist/i.test(String(e.message) + JSON.stringify(e.description || '')) ? 'inexistente' : 'erro'; }
}
const saida = {};
const espera = ms => new Promise(r => setTimeout(r, ms));
const prazo = Date.now() + 24000;                       // cada clique responde em ate ~24s (senao a internet corta)
const temTempo = ms => Date.now() + ms < prazo;
const AINDA = 'Ainda preparando a conexao do WhatsApp. Clique em "Conectar com QR code" de novo em alguns segundos.';
// "open" na Evolution nem sempre e verdade: se o celular removeu o aparelho, a sessao fica zumbi.
// Testa de verdade: pergunta ao WhatsApp se o proprio numero existe (so funciona com a conexao viva).
async function respondendo() {
  // o que a Evolution mostra no manager (connectionStatus). Obs.: o teste de "presenca" dava falso alarme
  // em conexao boa, entao nao e usado.
  try {
    const lista = await evo('GET', `/instance/fetchInstances?instanceName=${I}`);
    const inst = Array.isArray(lista) ? lista[0] : lista;
    return !!inst && (inst.connectionStatus || 'open') === 'open';
  } catch (e) { return true; }
}
async function apagarSessao() {   // desconecta e, se nao der, apaga a sessao inteira
  try { await evo('DELETE', `/instance/logout/${I}`); } catch (e) { /* zumbi nao aceita logout */ }
  await espera(1500);
  if ((await estado()) === 'open' || (await estado()) === 'connecting') {
    try { await evo('DELETE', `/instance/delete/${I}`); } catch (e) { /* ja apagada */ }
    await espera(2000);
  }
  if ((await estado()) === 'open' && temTempo(12000)) {   // zumbi teimoso: reinicia para a Evolution perceber, e apaga
    for (const m of ['POST', 'PUT']) { try { await evo(m, `/instance/restart/${I}`); break; } catch (e) { /* tenta o outro */ } }
    await espera(5000);
    try { await evo('DELETE', `/instance/logout/${I}`); } catch (e) { /* ok */ }
    try { await evo('DELETE', `/instance/delete/${I}`); } catch (e) { /* ok */ }
    await espera(2000);
  }
}
async function pedirQr(num) {
  for (let i = 0; i < 3 && temTempo(2500); i++) {   // logo apos criar, a Evolution as vezes ainda nao tem o QR pronto
    try {
      const q = await evo('GET', `/instance/connect/${I}` + (num ? `?number=${num}` : ''));
      if (q && (q.base64 || q.pairingCode)) return q;
    } catch (e) { /* ainda criando */ }
    await espera(2000);
  }
  return {};
}
if (corpo.op === 'conectar') {
  // "Conectar"/"Novo QR": sessao que nao esta aberta (QR vencido, limite de QRs, conexao pela metade)
  // e apagada e criada de novo -> QR novo de verdade, sempre.
  const criar = async () => {   // logo depois de apagar, a Evolution ainda esta limpando: tenta algumas vezes
    for (let i = 0; i < 4; i++) {
      try {
        await evo('POST', '/instance/create', { instanceName: I, token: TOKEN,
          integration: 'WHATSAPP-BAILEYS', qrcode: true, ...CONFIG_INSTANCIA, webhook: cfgWebhook });
        await espera(1500);
        return true;
      } catch (e) {
        if (!temTempo(5000)) return false;   // a Evolution ainda esta limpando a sessao antiga: o proximo clique cria
        await espera(3000);
      }
    }
    return false;
  };
  const num = String(corpo.numero || '').replace(/\D/g, '');
  let st = await estado();
  if (st === 'erro') throw new Error('Evolution (WhatsApp) fora do ar ou reiniciando. Tente de novo em 1 minuto.');
  if (st === 'open' && !(await respondendo())) {   // dizia conectado, mas a conexao tinha caido
    await apagarSessao();
    st = await estado();
    saida.aviso_zumbi = true;
  }
  if (st !== 'open' && st !== 'inexistente') {   // zera a sessao (QR vencido / limite de QRs) sem apagar
    try { await evo('DELETE', `/instance/logout/${I}`); } catch (e) { /* ja estava zerado */ }
    await espera(1500);
    st = await estado();
  }
  if (st === 'inexistente' && !(await criar())) { saida.aviso = AINDA; }
  else {
  await evo('POST', `/webhook/set/${I}`, { webhook: cfgWebhook });
  await evo('POST', `/settings/set/${I}`, CONFIG_INSTANCIA);
  if ((await estado()) !== 'open') {
    let q = await pedirQr(num);
    if (!q.base64 && !q.pairingCode && temTempo(12000)) {   // sessao travada de vez: apaga e cria do zero
      try { await evo('DELETE', `/instance/logout/${I}`); } catch (e) { /* ok */ }
      try { await evo('DELETE', `/instance/delete/${I}`); } catch (e) { /* ok */ }
      await espera(3000);
      await criar();
      await evo('POST', `/webhook/set/${I}`, { webhook: cfgWebhook });
      q = await pedirQr(num);
    }
    saida.qr = q.base64 || null;
    saida.codigo = q.pairingCode || null;
    if (!saida.qr && !saida.codigo) saida.aviso = AINDA;
  }
  }
} else if (corpo.op === 'qr') {
  // enquanto espera a leitura: so pega o QR atual (o WhatsApp troca o QR sozinho a cada ~20s), sem zerar nada
  if ((await estado()) === 'connecting') {
    try { const q = await evo('GET', `/instance/connect/${I}`); saida.qr = q.base64 || null; } catch (e) { /* tenta de novo */ }
  }
} else if (corpo.op === 'puxar') {
  // mensagens que a Evolution guardou desde a ultima que a IA leu (max 7 dias). Vao pelo canal normal,
  // marcadas como historico: a IA so le e aprende, nunca responde mensagem antiga. Repetidas sao ignoradas.
  const desde = Math.max(+corpo.desde || 0, Math.floor(Date.now() / 1000) - 7 * 86400) - 120;
  const lista = await evo('GET', `/instance/fetchInstances?instanceName=${I}`);
  const inst = Array.isArray(lista) ? lista[0] : lista;
  const dono = String((inst && (inst.ownerJid || inst.owner)) || '').split('@')[0];
  const achadas = [];
  let pagina = 1, paginas = 1;
  while (pagina <= paginas && pagina <= 30 && temTempo(6000)) {
    const r = await evo('POST', `/chat/findMessages/${I}`, {
      where: { messageTimestamp: { gte: new Date(desde * 1000).toISOString(), lte: new Date().toISOString() } }, page: pagina, offset: 100 });
    const m = (r && r.messages) || {};
    paginas = m.pages || 1;
    for (const x of m.records || []) achadas.push(x);
    pagina++;
  }
  achadas.sort((a, b) => (+a.messageTimestamp || 0) - (+b.messageTimestamp || 0));
  let enviadas = 0;
  for (const x of achadas) {
    if (!temTempo(1500)) break;
    const jid = (x.key && x.key.remoteJid) || '';
    if (!jid.endsWith('@s.whatsapp.net') && !jid.endsWith('@lid')) continue;   // grupos/status: ignora
    try {
      await this.helpers.httpRequest({ method: 'POST', url: urlWebhook, json: true, timeout: 8000,
        body: { event: 'messages.upsert', instance: I, apikey: TOKEN, sender: `${dono}@s.whatsapp.net`, historico: true,
                data: { key: x.key, pushName: x.pushName || '', message: x.message || {}, messageTimestamp: x.messageTimestamp } } });
      enviadas++;
    } catch (e) { /* segue */ }
  }
  saida.puxadas = enviadas;
  saida.encontradas = achadas.length;
  saida.desde = desde;
  saida.mais = pagina <= paginas || enviadas < achadas.filter(x => ((x.key && x.key.remoteJid) || '').match(/@(s\.whatsapp\.net|lid)$/)).length;
} else if (corpo.op === 'desconectar') {
  const tentar = async () => {
    try { await evo('DELETE', `/instance/logout/${I}`); } catch (e) { /* zumbi nao aceita logout */ }
    await espera(1000);
    try { await evo('DELETE', `/instance/delete/${I}`); } catch (e) { /* recusou ou ja apagada */ }
    await espera(1500);
  };
  await tentar();
  if ((await estado()) === 'open') {
    // sessao zumbi (o celular ja removeu o aparelho): reiniciar faz a Evolution perceber que caiu
    for (const m of ['POST', 'PUT']) { try { await evo(m, `/instance/restart/${I}`); break; } catch (e) { /* tenta o outro */ } }
    await espera(6000);
    await tentar();
  }
  const st = await estado();
  // ainda "open" mas sem responder = morta de qualquer jeito: conta como desconectada
  saida.desconectado = st !== 'open' || !(await respondendo());
  if (st === 'open' && saida.desconectado) saida.zumbi = true;
}
saida.estado = await estado();
// status: "open" so vale se a conexao responde (senao mostra como caida, com explicacao)
if (saida.estado === 'open' && temTempo(8000) && !(await respondendo())) { saida.estado = 'close'; saida.zumbi = true; }
if (saida.estado !== 'inexistente' && saida.estado !== 'erro') {
  try { await evo('POST', `/settings/set/${I}`, CONFIG_INSTANCIA); } catch (e) { /* tenta na proxima */ }
}
saida.config = corpo.config || {};
if (saida.estado === 'open') {
  try {
    const lista = await evo('GET', `/instance/fetchInstances?instanceName=${I}`);
    const i = Array.isArray(lista) ? lista[0] : lista;
    saida.numero = String(i.ownerJid || i.owner || '').split('@')[0];
    saida.perfil = i.profileName || null;
  } catch (e) { /* sem detalhes */ }
}
saida.instancia = I;
saida.desconhecidos = corpo.desconhecidos || [];
return [{ json: saida }];

